import{_ as a,H as t,f as s,i as o}from"./chunks/framework.CSxcEb-0.js";const p=JSON.parse('{"title":"Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),n={name:"guide/tasks.md"};function r(i,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h1><p>The <strong>Tasks</strong> view is where you create and triage work before it lands on the calendar.</p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><h3 id="list-mode" tabindex="-1">List mode <a class="header-anchor" href="#list-mode" aria-label="Permalink to &quot;List mode&quot;">​</a></h3><p>Best for fast editing: search, complete tasks, and review metadata (due date, duration, list, priority).</p><h3 id="kanban-mode" tabindex="-1">Kanban mode <a class="header-anchor" href="#kanban-mode" aria-label="Permalink to &quot;Kanban mode&quot;">​</a></h3><p>Columns follow your <strong>lists</strong>. Drag cards between columns to change list assignment or stage-style workflow.</p><h3 id="eisenhower-mode" tabindex="-1">Eisenhower mode <a class="header-anchor" href="#eisenhower-mode" aria-label="Permalink to &quot;Eisenhower mode&quot;">​</a></h3><p>Sorts tasks into urgency/importance quadrants for prioritization. Inbox behavior can be toggled in Settings (show inbox in matrix).</p><h2 id="creating-tasks" tabindex="-1">Creating tasks <a class="header-anchor" href="#creating-tasks" aria-label="Permalink to &quot;Creating tasks&quot;">​</a></h2><p>When adding a task, set at minimum:</p><ul><li><strong>Title</strong></li><li><strong>List</strong> (or default list from Settings)</li><li><strong>Due date</strong> — required for scheduling placement</li><li><strong>Duration</strong> — minutes of work the scheduler should allocate</li></ul><p>Optional: priority (if enabled in Settings), dependencies, splittable flag, notes, repeat rules.</p><h2 id="list-filters" tabindex="-1">List filters <a class="header-anchor" href="#list-filters" aria-label="Permalink to &quot;List filters&quot;">​</a></h2><p>Use <strong>sidebar list chips</strong> to focus on one list (including Inbox). Filtering hides other lists from task views and can affect what you see on the calendar sidebar context.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Link tasks so one must finish before another starts. The scheduler uses a topological sort; cycles are rejected.</p><p><strong>Dependency drag direction</strong> (Settings): controls whether dragging a link means “target depends on dragged” or the reverse — match your mental model and stick to one setting.</p><h2 id="completion-and-auto-schedule" tabindex="-1">Completion and auto-schedule <a class="header-anchor" href="#completion-and-auto-schedule" aria-label="Permalink to &quot;Completion and auto-schedule&quot;">​</a></h2><p>Completing a task removes it from scheduling. Editing due date, duration, list hours profile, or dependencies triggers a reschedule pass (same as adding/deleting tasks).</p><p>See <a href="./calendar.html">Calendar</a> for placement and lock behavior after tasks are scheduled.</p>',21)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
